INSERT INTO base_example (suite, title, kind, expected, description, sql) VALUES
('fiber_unrank','centered_hexagonal_numbers: element_at == iterator','eq','true','direct unrank agrees with the floor',$q$ SELECT coalesce(bool_and((element_at(f, r)).value = (SELECT (e).value FROM elements(f, r+1) e ORDER BY e OFFSET r LIMIT 1)), true)::text FROM fibers(centered_hexagonal_numbers()) f, generate_series(0, 8) r WHERE r < cardinality(f) $q$),
